def size_qdrant_int8_memory_gb(num_vectors_billions: float, dim: int = 1536, hnsw_overhead_b: int = 384) -> float:
    bytes_per_vec = dim + hnsw_overhead_b
    total_bytes = num_vectors_billions * 1e9 * bytes_per_vec
    return round(total_bytes / (1024**3), 1)

service AgenticMemoryService {
  rpc RecallMemory (RecallRequest) returns (RecallResponse);
  rpc IngestTurn (IngestRequest) returns (IngestAck);
  rpc PurgeNamespace (PurgeRequest) returns (PurgeStatus);
