def rrf_plus_decay(ranks: list[int], retention_score: float, k: int = 60) -> float:
    rrf = sum(1.0 / (k + r) for r in ranks)
    return rrf * (0.5 + 0.5 * retention_score)

def assemble_degraded_response(t1_hits: list, t2_hits: list, t3_hits: list | None) -> dict:
    degraded = [] if t3_hits is not None else ["tier3_graph"]
    merged = t1_hits + t2_hits + (t3_hits or [])
    return {"facts": merged, "degraded_tiers": degraded}

def check_tombstone_before_decrypt(is_tombstoned: bool, dek_active: bool) -> bool:
    if is_tombstoned or not dek_active:
        return False
    return True
